type Props = { height?: number };

export function CreateOutfitIllustration({ height = 140 }: Props) {
  return <SvgXml xml={MIRROR_XML} width={(97 / 140) * height} height={height} />;
}

export function BuildWardrobeIllustration({ height = 140 }: Props) {
  return <SvgXml xml={CLOTHES_XML} width={(117 / 140) * height} height={height} />;
}
